type ApiResult<T> =
  | { ok: true; data: T }
  | { ok: false; error: string; code: number };

function handleResult<T>(result: ApiResult<T>): T {
  switch (result.ok) {
    case true:
      return result.data;
    case false:
      throw new Error(`[${result.code}] ${result.error}`);
    default:
      const _exhaustive: never = result;
      return _exhaustive;
  }
}

type Action =
  | { type: 'user/loaded'; payload: User }
  | { type: 'user/error'; message: string }
  | { type: 'user/logout' };

function reducer(state: State, action: Action): State {
  switch (action.type) {
    case 'user/loaded':
      return { ...state, user: action.payload };
    case 'user/error':
      return { ...state, error: action.message };
    case 'user/logout':
      return { ...state, user: null };
    default:
      return action satisfies never;
  }
}

type FetchOutcome<T> =
  | { kind: 'success'; status: number; body: T }
  | { kind: 'http-error'; status: number; body: string }
  | { kind: 'network'; cause: unknown };

async function fetchJson<T>(url: string, isT: (x: unknown) => x is T): Promise<FetchOutcome<T>> {
  try {
    const res = await fetch(url);
    const raw: unknown = await res.json();
    if (!res.ok) return { kind: 'http-error', status: res.status, body: String(raw) };
    if (!isT(raw)) return { kind: 'http-error', status: 502, body: 'Invalid JSON shape' };
    return { kind: 'success', status: res.status, body: raw };
  } catch (cause) {
    return { kind: 'network', cause };
  }
}

